package com.asmj.marketplace.rewards;
import java.math.BigDecimal;import java.time.Instant;import java.time.LocalDate;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;
@Document(collection="seller_reward_awards")
public class SellerRewardAward {
 @Id private String id;@Indexed private String vendorUserId;private String vendorName,rewardTitle;private LocalDate periodStart,periodEnd;private int rank,completedOrders;private BigDecimal salesValue,averageRating,cancellationRate,rewardAmount;private Instant publishedAt;
 public String getId(){return id;}public void setId(String v){id=v;}public String getVendorUserId(){return vendorUserId;}public void setVendorUserId(String v){vendorUserId=v;}public String getVendorName(){return vendorName;}public void setVendorName(String v){vendorName=v;}public String getRewardTitle(){return rewardTitle;}public void setRewardTitle(String v){rewardTitle=v;}public LocalDate getPeriodStart(){return periodStart;}public void setPeriodStart(LocalDate v){periodStart=v;}public LocalDate getPeriodEnd(){return periodEnd;}public void setPeriodEnd(LocalDate v){periodEnd=v;}public int getRank(){return rank;}public void setRank(int v){rank=v;}public int getCompletedOrders(){return completedOrders;}public void setCompletedOrders(int v){completedOrders=v;}public BigDecimal getSalesValue(){return salesValue;}public void setSalesValue(BigDecimal v){salesValue=v;}public BigDecimal getAverageRating(){return averageRating;}public void setAverageRating(BigDecimal v){averageRating=v;}public BigDecimal getCancellationRate(){return cancellationRate;}public void setCancellationRate(BigDecimal v){cancellationRate=v;}public BigDecimal getRewardAmount(){return rewardAmount;}public void setRewardAmount(BigDecimal v){rewardAmount=v;}public Instant getPublishedAt(){return publishedAt;}public void setPublishedAt(Instant v){publishedAt=v;}
}
